  1→/**
  2→ * Mock Delegated Routing Service for E2E Testing
  3→ *
  4→ * Implements the IPFS delegated routing API for IPNS records:
  5→ * - PUT /routing/v1/ipns/{name} - Store an IPNS record
  6→ * - GET /routing/v1/ipns/{name} - Retrieve an IPNS record
  7→ *
  8→ * Records are stored in-memory and reset when the service restarts.
  9→ * This allows E2E tests to run without polluting the public IPFS DHT
 10→ * and avoids sequence number conflicts from repeated test runs.
 11→ */
 12→
 13→import Fastify from 'fastify';
 14→
 15→const fastify = Fastify({
 16→  logger: {
 17→    level: process.env.LOG_LEVEL ?? 'info',
 18→    transport:
 19→      process.env.NODE_ENV !== 'production'
 20→        ? { target: 'pino-pretty', options: { colorize: true } }
 21→        : undefined,
 22→  },
 23→});
 24→
 25→// In-memory storage for IPNS records
 26→// Key: IPNS name (k51... or bafzaa...), Value: raw record bytes
 27→const ipnsRecords = new Map<string, Buffer>();
 28→
 29→// Health check endpoint
 30→fastify.get('/health', async () => {
 31→  return { status: 'ok', records: ipnsRecords.size };
 32→});
 33→
 34→// GET /routing/v1/ipns/{name} - Retrieve IPNS record
 35→fastify.get<{ Params: { name: string } }>('/routing/v1/ipns/:name', async (request, reply) => {
 36→  const { name } = request.params;
 37→
 38→  const record = ipnsRecords.get(name);
 39→  if (!record) {
 40→    return reply.status(404).send({
 41→      error: 'record not found',
 42→      name,
 43→    });
 44→  }
 45→
 46→  fastify.log.info({ name, size: record.length }, 'Retrieved IPNS record');
 47→
 48→  return reply.status(200).header('Content-Type', 'application/vnd.ipfs.ipns-record').send(record);
 49→});
 50→
 51→// PUT /routing/v1/ipns/{name} - Store IPNS record
 52→fastify.put<{ Params: { name: string } }>('/routing/v1/ipns/:name', async (request, reply) => {
 53→  const { name } = request.params;
 54→
 55→  // Get raw body as Buffer
 56→  const body = request.body as Buffer;
 57→  if (!body || body.length === 0) {
 58→    return reply.status(400).send({
 59→      error: 'empty request body',
 60→    });
 61→  }
 62→
 63→  // Store the record (overwrites any existing record)
 64→  // Note: We intentionally don't validate sequence numbers here.
 65→  // This allows tests to reset state by simply restarting the service.
 66→  ipnsRecords.set(name, body);
 67→
 68→  fastify.log.info(
 69→    { name, size: body.length, totalRecords: ipnsRecords.size },
 70→    'Stored IPNS record'
 71→  );
 72→
 73→  return reply.status(200).send({ ok: true });
 74→});
 75→
 76→// Configure to accept raw binary bodies
 77→fastify.addContentTypeParser(
 78→  'application/vnd.ipfs.ipns-record',
 79→  { parseAs: 'buffer' },
 80→  async (_request: unknown, payload: Buffer) => payload
 81→);
 82→
 83→// Also accept application/octet-stream for compatibility
 84→fastify.addContentTypeParser(
 85→  'application/octet-stream',
 86→  { parseAs: 'buffer' },
 87→  async (_request: unknown, payload: Buffer) => payload
 88→);
 89→
 90→// Reset endpoint for tests - clears all stored records
 91→fastify.post('/reset', async () => {
 92→  const count = ipnsRecords.size;
 93→  ipnsRecords.clear();
 94→  fastify.log.info({ clearedRecords: count }, 'Reset all IPNS records');
 95→  return { ok: true, clearedRecords: count };
 96→});
 97→
 98→// Start server
 99→const start = async () => {
100→  const host = process.env.HOST ?? '0.0.0.0';
101→  const port = parseInt(process.env.PORT ?? '3001', 10);
102→
103→  try {
104→    await fastify.listen({ host, port });
105→    fastify.log.info(`Mock IPNS routing service listening on http://${host}:${port}`);
106→    fastify.log.info('Endpoints:');
107→    fastify.log.info('  GET  /health - Health check');
108→    fastify.log.info('  GET  /routing/v1/ipns/:name - Get IPNS record');
109→    fastify.log.info('  PUT  /routing/v1/ipns/:name - Store IPNS record');
110→    fastify.log.info('  POST /reset - Clear all records');
111→  } catch (err) {
112→    fastify.log.error(err);
113→    process.exit(1);
114→  }
115→};
116→
117→start();
118→

  1→import { HttpException, HttpStatus } from '@nestjs/common';
  2→import { ConfigService } from '@nestjs/config';
  3→import { DelegatedRoutingClient } from './delegated-routing.client';
  4→
  5→// Mock global fetch
  6→const mockFetch = jest.fn();
  7→global.fetch = mockFetch;
  8→
  9→function createMockResponse(
 10→  status: number,
 11→  opts: { body?: string; buffer?: ArrayBuffer; headers?: Record<string, string> } = {}
 12→): Response {
 13→  const { body = '', buffer, headers = {} } = opts;
 14→  const headerMap = new Map(Object.entries(headers));
 15→  return {
 16→    ok: status >= 200 && status < 300,
 17→    status,
 18→    headers: { get: (key: string) => headerMap.get(key) ?? null },
 19→    text: jest.fn().mockResolvedValue(body),
 20→    arrayBuffer: jest.fn().mockResolvedValue(buffer ?? new ArrayBuffer(0)),
 21→  } as unknown as Response;
 22→}
 23→
 24→describe('DelegatedRoutingClient', () => {
 25→  let client: DelegatedRoutingClient;
 26→  let configService: ConfigService;
 27→  // eslint-disable-next-line @typescript-eslint/no-explicit-any
 28→  let delaySpy: jest.SpyInstance<Promise<void>, [ms: number], any>;
 29→
 30→  beforeEach(() => {
 31→    jest.restoreAllMocks();
 32→    mockFetch.mockReset();
 33→
 34→    configService = {
 35→      get: jest.fn().mockReturnValue('https://routing.example.com'),
 36→    } as unknown as ConfigService;
 37→
 38→    client = new DelegatedRoutingClient(configService);
 39→
 40→    // Eliminate real delays by making delay() resolve instantly
 41→    delaySpy = jest.spyOn(client as never, 'delay' as never).mockResolvedValue(undefined as never);
 42→  });
 43→
 44→  describe('constructor', () => {
 45→    it('reads DELEGATED_ROUTING_URL from config', () => {
 46→      expect(configService.get).toHaveBeenCalledWith(
 47→        'DELEGATED_ROUTING_URL',
 48→        'https://delegated-ipfs.dev'
 49→      );
 50→    });
 51→  });
 52→
 53→  describe('publish', () => {
 54→    const ipnsName = 'k51qzi5uqu5dg12345';
 55→    const recordBytes = new Uint8Array([1, 2, 3]);
 56→
 57→    it('publishes successfully on first attempt', async () => {
 58→      mockFetch.mockResolvedValueOnce(createMockResponse(200));
 59→
 60→      await client.publish(ipnsName, recordBytes);
 61→
 62→      expect(mockFetch).toHaveBeenCalledTimes(1);
 63→      const [url, init] = mockFetch.mock.calls[0];
 64→      expect(url).toBe(
 65→        `https://routing.example.com/routing/v1/ipns/${encodeURIComponent(ipnsName)}`
 66→      );
 67→      expect(init.method).toBe('PUT');
 68→      expect(init.headers['Content-Type']).toBe('application/vnd.ipfs.ipns-record');
 69→    });
 70→
 71→    it('throws BAD_GATEWAY on non-retryable HTTP error', async () => {
 72→      mockFetch.mockResolvedValue(createMockResponse(500, { body: 'Internal Server Error' }));
 73→
 74→      const error = await client.publish(ipnsName, recordBytes).catch((e) => e);
 75→
 76→      expect(error).toBeInstanceOf(HttpException);
 77→      expect(error.getStatus()).toBe(HttpStatus.BAD_GATEWAY);
 78→      // Should not retry — only one fetch call
 79→      expect(mockFetch).toHaveBeenCalledTimes(1);
 80→    });
 81→
 82→    it('retries on network errors with exponential backoff', async () => {
 83→      mockFetch
 84→        .mockRejectedValueOnce(new Error('fetch failed'))
 85→        .mockRejectedValueOnce(new Error('fetch failed'))
 86→        .mockResolvedValueOnce(createMockResponse(200));
 87→
 88→      await client.publish(ipnsName, recordBytes);
 89→
 90→      expect(mockFetch).toHaveBeenCalledTimes(3);
 91→      // Delay called twice (attempts 0 and 1)
 92→      expect(delaySpy).toHaveBeenCalledTimes(2);
 93→      expect(delaySpy).toHaveBeenNthCalledWith(1, 1000); // 1000 * 2^0
 94→      expect(delaySpy).toHaveBeenNthCalledWith(2, 2000); // 1000 * 2^1
 95→    });
 96→
 97→    it('throws BAD_GATEWAY after exhausting retries on network errors', async () => {
 98→      mockFetch.mockRejectedValue(new Error('fetch failed'));
 99→
100→      const error = await client.publish(ipnsName, recordBytes).catch((e) => e);
101→
102→      expect(error).toBeInstanceOf(HttpException);
103→      expect(error.getStatus()).toBe(HttpStatus.BAD_GATEWAY);
104→      expect(mockFetch).toHaveBeenCalledTimes(3);
105→      // Delay called for attempts 0 and 1, not for last attempt
106→      expect(delaySpy).toHaveBeenCalledTimes(2);
107→    });
108→
109→    it('retries on 429 with Retry-After header', async () => {
110→      mockFetch
111→        .mockResolvedValueOnce(createMockResponse(429, { headers: { 'Retry-After': '2' } }))
112→        .mockResolvedValueOnce(createMockResponse(200));
113→
114→      await client.publish(ipnsName, recordBytes);
115→
116→      expect(mockFetch).toHaveBeenCalledTimes(2);
117→      expect(delaySpy).toHaveBeenCalledWith(2000); // 2 seconds from Retry-After
118→    });
119→
120→    it('skips sleeping on 429 on last retry attempt', async () => {
121→      mockFetch.mockResolvedValue(createMockResponse(429, { headers: { 'Retry-After': '5' } }));
122→
123→      const error = await client.publish(ipnsName, recordBytes).catch((e) => e);
124→
125→      expect(error).toBeInstanceOf(HttpException);
126→      expect(mockFetch).toHaveBeenCalledTimes(3);
127→      // Should only delay for first 2 attempts, skip delay on last
128→      expect(delaySpy).toHaveBeenCalledTimes(2);
129→    });
130→
131→    it('uses abort signal for timeout', async () => {
132→      mockFetch.mockResolvedValueOnce(createMockResponse(200));
133→
134→      await client.publish(ipnsName, recordBytes);
135→
136→      const [, init] = mockFetch.mock.calls[0];
137→      expect(init.signal).toBeInstanceOf(AbortSignal);
138→    });
139→  });
140→
141→  describe('resolve', () => {
142→    const ipnsName = 'k51qzi5uqu5dg12345';
143→    const testBuffer = new Uint8Array([10, 20, 30]).buffer;
144→
145→    function okResponse() {
146→      return {
147→        ok: true,
148→        status: 200,
149→        headers: { get: () => null },
150→        arrayBuffer: jest.fn().mockResolvedValue(testBuffer),
151→      } as unknown as Response;
152→    }
153→
154→    it('resolves successfully and returns Uint8Array', async () => {
155→      mockFetch.mockResolvedValueOnce(okResponse());
156→
157→      const result = await client.resolve(ipnsName);
158→
159→      expect(result).toBeInstanceOf(Uint8Array);
160→      expect(mockFetch).toHaveBeenCalledTimes(1);
161→      const [url, init] = mockFetch.mock.calls[0];
162→      expect(url).toBe(
163→        `https://routing.example.com/routing/v1/ipns/${encodeURIComponent(ipnsName)}`
164→      );
165→      expect(init.method).toBe('GET');
166→      expect(init.headers.Accept).toBe('application/vnd.ipfs.ipns-record');
167→    });
168→
169→    it('returns null for 404 (IPNS name not found)', async () => {
170→      mockFetch.mockResolvedValueOnce(createMockResponse(404));
171→
172→      const result = await client.resolve(ipnsName);
173→
174→      expect(result).toBeNull();
175→      expect(mockFetch).toHaveBeenCalledTimes(1);
176→    });
177→
178→    it('throws BAD_GATEWAY on non-retryable HTTP error', async () => {
179→      mockFetch.mockResolvedValue(createMockResponse(500, { body: 'error' }));
180→
181→      const error = await client.resolve(ipnsName).catch((e) => e);
182→
183→      expect(error).toBeInstanceOf(HttpException);
184→      expect(error.getStatus()).toBe(HttpStatus.BAD_GATEWAY);
185→      expect(mockFetch).toHaveBeenCalledTimes(1);
186→    });
187→
188→    it('retries on network errors', async () => {
189→      mockFetch
190→        .mockRejectedValueOnce(new Error('network error'))
191→        .mockResolvedValueOnce(okResponse());
192→
193→      const result = await client.resolve(ipnsName);
194→
195→      expect(result).toBeInstanceOf(Uint8Array);
196→      expect(mockFetch).toHaveBeenCalledTimes(2);
197→      expect(delaySpy).toHaveBeenCalledWith(1000);
198→    });
199→
200→    it('retries on 429 with Retry-After', async () => {
201→      mockFetch
202→        .mockResolvedValueOnce(createMockResponse(429, { headers: { 'Retry-After': '1' } }))
203→        .mockResolvedValueOnce(okResponse());
204→
205→      const result = await client.resolve(ipnsName);
206→
207→      expect(result).toBeInstanceOf(Uint8Array);
208→      expect(mockFetch).toHaveBeenCalledTimes(2);
209→      expect(delaySpy).toHaveBeenCalledWith(1000); // 1s from Retry-After
210→    });
211→
212→    it('re-throws HttpException without retrying', async () => {
213→      const httpError = new HttpException('custom error', HttpStatus.FORBIDDEN);
214→      mockFetch.mockRejectedValueOnce(httpError);
215→
216→      await expect(client.resolve(ipnsName)).rejects.toThrow(httpError);
217→      expect(mockFetch).toHaveBeenCalledTimes(1);
218→    });
219→
220→    it('throws BAD_GATEWAY after exhausting retries', async () => {
221→      mockFetch.mockRejectedValue(new Error('network error'));
222→
223→      const error = await client.resolve(ipnsName).catch((e) => e);
224→
225→      expect(error).toBeInstanceOf(HttpException);
226→      expect(error.getStatus()).toBe(HttpStatus.BAD_GATEWAY);
227→      expect(mockFetch).toHaveBeenCalledTimes(3);
228→    });
229→  });
230→
231→  describe('retry delay capping', () => {
232→    const ipnsName = 'k51test';
233→    const recordBytes = new Uint8Array([1]);
234→
235→    it('caps Retry-After delay at 30 seconds', async () => {
236→      mockFetch
237→        .mockResolvedValueOnce(createMockResponse(429, { headers: { 'Retry-After': '999' } }))
238→        .mockResolvedValueOnce(createMockResponse(200));
239→
240→      await client.publish(ipnsName, recordBytes);
241→
242→      expect(delaySpy).toHaveBeenCalledWith(30_000); // capped, not 999000
243→    });
244→
245→    it('uses exponential backoff fallback when no Retry-After header', async () => {
246→      mockFetch
247→        .mockResolvedValueOnce(createMockResponse(429))
248→        .mockResolvedValueOnce(createMockResponse(200));
249→
250→      await client.publish(ipnsName, recordBytes);
251→
252→      // Fallback for attempt 0: min(1000 * 2^0, 30000) = 1000ms
253→      expect(delaySpy).toHaveBeenCalledWith(1000);
254→    });
255→
256→    it('encodes ipnsName in URL to handle reserved characters', async () => {
257→      const weirdName = 'k51+special/chars?here';
